/* Explicit SI models with bounded inputs and assumptions; no simulation claims. */
const StudioEngineering=(()=>{
 const positive=(n,name,max=1e12)=>{if(typeof n!=='number'||!Number.isFinite(n)||n<=0||n>max)throw Error(name+' must be positive and at most '+max);return n;};
 function beam({lengthMm,widthMm,heightMm,forceN,modulusGPa,yieldMPa}){[lengthMm,widthMm,heightMm].forEach(n=>positive(n,'Dimension mm',100000));positive(forceN,'Load N',1e8);positive(modulusGPa,'Modulus GPa',2000);positive(yieldMPa,'Yield MPa',100000);const L=lengthMm/1000,b=widthMm/1000,h=heightMm/1000,I=b*h**3/12,stress=forceN*L*h/2/I/1e6,deflection=forceN*L**3/(3*modulusGPa*1e9*I)*1000;return {bendingStressMPa:stress,tipDeflectionMm:deflection,yieldSafetyFactor:yieldMPa/stress,smallDeflection: deflection<lengthMm/20};}
 function shaft({torqueNm,diameterMm,rpm,efficiency}){positive(torqueNm,'Torque Nm',1e8);positive(diameterMm,'Diameter mm',10000);positive(rpm,'RPM',1000000);positive(efficiency,'Efficiency',1);return {shearStressMPa:16*torqueNm/(Math.PI*(diameterMm/1000)**3)/1e6,mechanicalPowerW:torqueNm*rpm*Math.PI/30,inputPowerW:torqueNm*rpm*Math.PI/30/efficiency};}
 function drone({massKg,motors,thrustRatio,batteryWh,powerW,usableFraction}){positive(massKg,'Mass kg',10000);if(!Number.isInteger(motors)||motors<2||motors>16)throw Error('Use 2–16 motors.');positive(thrustRatio,'Thrust ratio',10);positive(batteryWh,'Battery Wh',100000);positive(powerW,'Average electrical power W',1e7);positive(usableFraction,'Usable energy fraction',1);return {hoverThrustPerMotorN:massKg*9.80665/motors,targetThrustPerMotorN:massKg*9.80665*thrustRatio/motors,estimatedMinutes:batteryWh*usableFraction/powerW*60};}
 function open(){modal('Engineering calculation lab',`<p>Ideal hand-calculation models. Inputs are explicit assumptions, not inferred from visual materials. Results do not establish component or flight safety.</p><label>Model<select id="labModel"><option value="beam">Cantilever · rectangular beam · tip load</option><option value="shaft">Solid circular shaft · torque & power</option><option value="drone">Drone · thrust & energy budget</option></select></label><div id="labFields"></div><div id="labResult" role="status"></div><p id="labError" role="alert"></p><button type="button" id="labDownload">Export calculation JSON</button>`,()=>false);const definitions={beam:[['lengthMm','Length mm',200],['widthMm','Width mm',20],['heightMm','Height mm',10],['forceN','Tip load N',100],['modulusGPa','Elastic modulus GPa',69],['yieldMPa','Assumed yield MPa',240]],shaft:[['torqueNm','Torque N·m',2],['diameterMm','Diameter mm',10],['rpm','Speed RPM',1200],['efficiency','Efficiency 0–1',.8]],drone:[['massKg','Mass kg',1.2],['motors','Motor count',4],['thrustRatio','Target thrust / weight',2],['batteryWh','Battery energy Wh',22.2],['powerW','Assumed average draw W',180],['usableFraction','Usable energy 0–1',.8]]};let result=null;const select=document.getElementById('labModel'),fields=document.getElementById('labFields'),error=document.getElementById('labError'),output=document.getElementById('labResult');const render=()=>{fields.innerHTML=definitions[select.value].map(([id,label,value])=>`<label>${label}<input type="number" id="lab_${id}" value="${value}" step="any" min="0" required></label>`).join('');result=null;output.textContent='';error.textContent='';};render();select.onchange=render;const button=document.querySelector('#modalForm>button[type=submit]');button.textContent='Calculate';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();try{const input=Object.fromEntries(definitions[select.value].map(([id])=>[id,Number(document.getElementById('lab_'+id).value)]));result={model:select.value,inputs:input,results:({beam,shaft,drone})[select.value](input),assumptions:select.value==='beam'?'Linear elastic Euler–Bernoulli cantilever, rectangular section, static tip load; no shear deformation, buckling, fatigue or stress concentrations.':select.value==='shaft'?'Solid circular shaft under pure torsion; no bending, keyways, fatigue, losses beyond the entered efficiency.':'Static weight distribution and constant entered electrical power; excludes flight dynamics, propeller efficiency, battery sag and reserves beyond the entered usable fraction.'};output.innerHTML=Object.entries(result.results).map(([k,v])=>`<p><b>${esc(k)}</b>: ${typeof v==='number'?v.toPrecision(6):v}</p>`).join('')+'<p>'+esc(result.assumptions)+'</p>';error.textContent='';}catch(e){result=null;error.textContent=e.message;output.textContent='';}};document.getElementById('labDownload').onclick=()=>{if(!result)return toast('Calculate valid inputs first.');download('engineering-calculation.json',JSON.stringify(result,null,2),'application/json');};}
 return {beam,shaft,drone,open};
})();
